@js:
sort=[];
push=(title,url,type1,type2)=>
	sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

//push("最近更新","/last",1,1);

